// ═══ MULTIPLE catch blocks — SPECIFIC before GENERAL ═══
try {
    tradeService.processFile("/trades.csv");
} catch (FileNotFoundException e) {       // MOST specific — checked first!
    log.warn("File not found — using fallback");
    useFallbackData();
} catch (IOException e) {                  // LESS specific (parent of FileNotFoundException)
    log.error("IO error reading file", e);
    alertOps("IO failure");
} catch (RuntimeException e) {             // UNCHECKED exceptions
    log.error("Unexpected runtime error", e);
} catch (Exception e) {                    // MOST general — catch-all LAST!
    log.error("Unhandled exception", e);
}

// ❌ WRONG ORDER — compile error!
// try { ... }
// catch (Exception e) { }           ← catches EVERYTHING — general first!
// catch (IOException e) { }          ← UNREACHABLE! COMPILE ERROR!
// "exception IOException has already been caught"

// ═══ MULTI-CATCH (Java 7) — one block for multiple types ═══
try {
    tradeService.processAndStore(data);
} catch (IOException | SQLException e) {
    // ONE block handles BOTH! No duplicate code.
    log.error("Data processing failed: {}", e.getMessage());
    // e is implicitly FINAL — cannot reassign:
    // e = new IOException("x");  → COMPILE ERROR! final in multi-catch
}

// Multi-catch RULE: exceptions must be UNRELATED (not parent-child)
// catch (IOException | FileNotFoundException e) → COMPILE ERROR!
// FileNotFoundException IS-A IOException — already caught by IOException.
// Use: catch (IOException | SQLException e) — unrelated types ✅
