// ─── File: src/test/java/com/bank/multicatch/MultiCatchTest.java ───
package com.bank.multicatch;

import com.bank.multicatch.service.FileProcessorService;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class MultiCatchTest {

    FileProcessorService service = new FileProcessorService();

    @Test
    void specificCatchFirst_fileNotFound() {
        String result = service.processWithCorrectOrder("notfound.csv");
        assertThat(result).startsWith("CATCH-1 (FileNotFound)");
        // FileNotFoundException caught by FIRST catch (most specific)
    }

    @Test
    void lesSpecific_ioException() {
        String result = service.processWithCorrectOrder("ioerror.csv");
        assertThat(result).startsWith("CATCH-2 (IOException)");
        // IOException caught by SECOND catch (FileNotFound didn't match)
    }

    @Test
    void unrelated_sqlException() {
        String result = service.processWithCorrectOrder("sqlerror.csv");
        assertThat(result).startsWith("CATCH-3 (SQLException)");
    }

    @Test
    void runtime_nullPointer() {
        String result = service.processWithCorrectOrder("nullbug.csv");
        assertThat(result).startsWith("CATCH-4 (Runtime)");
    }

    @Test
    void multiCatch_handlesIOandSQL() {
        assertThat(service.processWithMultiCatch("ioerror.csv")).startsWith("MULTI-CATCH");
        assertThat(service.processWithMultiCatch("sqlerror.csv")).startsWith("MULTI-CATCH");
        // SAME catch block handles BOTH types!
    }

    @Test
    void multiCatch_runtimeSeparate() {
        assertThat(service.processWithMultiCatch("nullbug.csv")).startsWith("RUNTIME");
        // RuntimeException has its own catch — not in multi-catch
    }

    @Test
    void success_noCatch() {
        assertThat(service.processWithCorrectOrder("valid.csv")).startsWith("Processed");
    }
}
